    for cell in row:
        if cell.value == "Code":
            code_row = cell.row
            break
    if code_row:
        break

# Delete blank rows above the "Code" row
if code_row:
    for row in range(1, code_row):
        # Check if the row is blank (all cells in the row are empty)
        is_blank = True
        for cell in ws[row]:
            if cell.value is not None:
                is_blank = False
                break
        if is_blank:
            ws.delete_rows(row)

# Save the modified workbook
wb.save('output.xlsx')
