from openpyxl import load_workbook

# Load the workbook and select the active sheet
wb = load_workbook("input.xlsx")
ws = wb.active

# Define ranges
month_names = [ws[f"B{row}"].value for row in range(3, 15)]  # B3:B14
month_end_dates = [ws[f"B{row}"].value for row in range(17, 25)]  # B17:B24
data_range = ws["C3:G24"]  # Data range to sum from

# Map month names to their corresponding total range in C3:G14
total_ranges = {
    month_names[i]: ws[f"C{3 + i}:G{3 + i}"] for i in range(len(month_names))
}

# Create a dictionary to map month end dates to their corresponding month name
date_to_month = {}
for i, date in enumerate(month_end_dates):
    # Extract the month from the date
    month = date.strftime("%b")  # e.g., "Jan", "Feb"
    # Find the corresponding month name in month_names
    for j, mn in enumerate(month_names):
        if mn == month:
            date_to_month[date] = mn
            break

# Initialize a dictionary to store sums for each month
month_sums = {mn: [0] * 5 for mn in month_names}

# Iterate over the data range and sum values based on the month
for row in data_range:
    for i, cell in enumerate(row):
        if cell.value is not None:
            # Get the date from B17:B24 corresponding to this row
            date_row = 17 + (i // 7)  # Calculate the corresponding row in B17:B24
            date = ws[f"B{date_row}"].value
            if date in date_to_month:
                month = date_to_month[date]
                month_sums[month][i % 7] += cell.value

# Write the computed sums to the total ranges
for month, ranges in total_ranges.items():
    for i, range_cell in enumerate(ranges):
        for cell in range_cell:
            if month_sums[month][i] > 0:
                cell.value = month_sums[month][i]
            else:
                cell.value = None  # Leave the cell empty if the sum is zero

# Save the workbook as output.xlsx
wb.save("output.xlsx")
