from openpyxl import load_workbook

# Load the workbook
wb = load_workbook('input.xlsx')
ws = wb['Sheet1']

# Read the data
data = []
for row in ws.iter_rows(min_row=2, max_row=13, values_only=True):
    if row[0] is not None:
        data.append(row)

# Calculate average turnaround time for each department
department_data = {}
for dept, status, time in data:
    if status in ["In Progress", "In Review"] and time >= 6:
        if dept not in department_data:
            department_data[dept] = []
        department_data[dept].append(time)

# Compute averages
averages = {}
for dept, times in department_data.items():
    average = sum(times) / len(times)
    averages[dept] = average

# Write results to the output range
result_row = 11
for row in ws.iter_rows(min_row=11, max_row=13, values_only=False):
    dept_cell = row[0]
    if dept_cell.value in averages:
        dept_cell.offset(row=0, column=1).value = averages[dept_cell.value]
    else:
        dept_cell.offset(row=0, column=1).value = ""

# Save the workbook
wb.save('output.xlsx')
